import random
import math

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def generate_tseitin_formula(n):
        literals = list(range(1, n + 1))
        clauses = []

        # Generate a conjunction of n literals
        for i in range(n):
            clause = [literals[i]]
            clauses.append(clause)

        # Add a clause with all literals negated
        for i in range(n):
            clause = [-literals[i]]
            clauses.append(clause)

        # Add clauses to ensure each literal appears exactly once
        for i in range(1, n + 1):
            clause = [i]
            for j in range(i + 1, n + 1):
                clause.append(-j)
            clauses.append(clause)

        return literals, clauses

    def resolution_width(clauses):
        # Simplified resolution width calculation
        return len(clauses)

    def min_monomials_per_clause(clauses):
        monomials = {}
        for clause in clauses:
            if len(clause) == 1:
                continue
            for lit in clause:
                if abs(lit) not in monomials:
                    monomials[abs(lit)] = 1
                else:
                    monomials[abs(lit)] += 1
        return monomials

    n = random.choice([5, 10, 15, 20, 30, 40])
    literals, clauses = generate_tseitin_formula(n)

    w_phi = resolution_width(clauses)
    M_phi = min_monomials_per_clause(clauses)

    metric_value = sum(M_phi.values())
    conjecture_holds = abs(w_phi - metric_value) <= 2 * metric_value

    return {
        "metric_name": "resolution_width",
        "metric_value": w_phi,
        "instances_tested": len(clauses),
        "n_max": n,
        "conjecture_holds": conjecture_holds,
        "counterexample": "" if conjecture_holds else "mapping_undefined"
    }

